content.content:
1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18		"sort"
19		"strings"
20	)
21	
22	// SnapshotFormatVersion is the only on-disk snapshot format understood.
23	const SnapshotFormatVersion = 1
24	
25	// SnapshotFile is the on-disk representation of one frozen lineage graph.
26	//
27	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
28	// verified against Graph on every read; Graph carries the complete graph.
29	type SnapshotFile struct {
30		FormatVersion int       `json:"formatVersion"`
31		ContentID     string    `json:"contentId"`
32		Graph         GraphFile `json:"graph"`
33	}
34	
35	// RootSourceChange reports that one dataset present in BOTH versions reaches a
36	// different set of root sources. OldRoots and NewRoots are sorted by name and
37	// never nil, so empty root sets encode as [] rather than null.
38	type RootSourceChange struct {
39		Dataset  string   `json:"dataset"`
40		OldRoots []string `json:"oldRoots"`
41		NewRoots []string `json:"newRoots"`
42	}
43	
44	// CompareReport is the deterministic, read-only diff of two snapshots read in
45	// the fixed direction old -> new.
46	//
47	// NewDatasets and RemovedDatasets list nodes present on only one side.
48	// ChangedDatasets lists datasets present on both sides whose direct upstream
49	// set actually changed. AddedRelations and RemovedRelations list every
50	// directed edge present on only one side, including edges that vanish because
51	// one endpoint node was removed. RootSourceChanges covers only datasets common
52	// to both versions whose reachable root set differs; added or removed datasets
53	// never appear there.
54	type CompareReport struct {
55		NewDatasets       []string           `json:"newDatasets"`
56		RemovedDatasets   []string           `json:"removedDatasets"`
57		ChangedDatasets   []string           `json:"changedDatasets"`
58		AddedRelations    []Relation         `json:"addedRelations"`
59		RemovedRelations  []Relation         `json:"removedRelations"`
60		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
61	}
62	
63	// contentIDPrefix names the hash algorithm used for content addressing.
64	const contentIDPrefix = "sha256:"
65	
66	// graphAdjacencyFromFile builds the validated, normalized parent adjacency
67	// directly from a parsed graph file. It rejects empty names, duplicate
68	// datasets, and references to upstreams that are not declared; cycle checking
69	// is the caller's responsibility (via validateAcyclic) so the reported reason
70	// stays specific.
71	func graphAdjacencyFromFile(gf GraphFile) (adjacency, error) {
72		adj := make(adjacency, len(gf.Datasets))
73		for _, ds := range gf.Datasets {
74			if ds.Name == "" {
75				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
76			}
77			if _, exists := adj[ds.Name]; exists {
78				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
79			}
80			adj[ds.Name] = uniqueSorted(ds.Upstreams)
81		}
82		for name, parents := range adj {
83			for _, parent := range parents {
84				if _, ok := adj[parent]; !ok {
85					return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
86				}
87			}
88		}
89		return adj, nil
90	}
91	
92	// canonicalGraph serializes the graph's semantics deterministically: datasets
93	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
94	// JSON with no insignificant whitespace. Two semantically equal graphs always
95	// produce identical bytes.
96	func canonicalGraph(adj adjacency) ([]byte, error) {
97		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
98		return json.Marshal(gf)
99	}
100	
101	// computeContentID returns the content identifier of the graph bytes:
102	// "sha256:" followed by the lowercase hex SHA-256 digest.
103	func computeContentID(canonical []byte) string {
104		sum := sha256.Sum256(canonical)
105		return contentIDPrefix + hex.EncodeToString(sum[:])
106	}
107	
108	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
109	// version 1 and the matching content identifier. It does not mutate graph. The
110	// returned document and its serialized bytes depend only on graph semantics.
111	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
112		if err := ValidateGraph(graph); err != nil {
113			return nil, err
114		}
115		adj, err := graphAdjacency(graph)
116		if err != nil {
117			return nil, err
118		}
119		canonical, err := canonicalGraph(adj)
120		if err != nil {
121			return nil, err
122		}
123		return &SnapshotFile{
124			FormatVersion: SnapshotFormatVersion,
125			ContentID:     computeContentID(canonical),
126			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
127		}, nil
128	}
129	
130	// MarshalSnapshot serializes a snapshot the same way for every save: indented
131	// JSON keyed by struct field order, terminated by a single newline.
132	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
133		var buf bytes.Buffer
134		enc := json.NewEncoder(&buf)
135		enc.SetIndent("", "  ")
136		enc.SetEscapeHTML(false)
137		if err := enc.Encode(snap); err != nil {
138			return nil, err
139		}
140		return buf.Bytes(), nil
141	}
142	
143	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
144	// can distinguish "field absent" from "field present with a zero value"
145	// (e.g. a missing formatVersion must be rejected rather than read as 0).
146	type rawSnapshot struct {
147		FormatVersion json.RawMessage `json:"formatVersion"`
148		ContentID     json.RawMessage `json:"contentId"`
149		Graph         json.RawMessage `json:"graph"`
150	}
151	
152	// isJSONNull reports whether a raw JSON value is the literal null.
153	func isJSONNull(raw json.RawMessage) bool {
154		return string(bytes.TrimSpace(raw)) == "null"
155	}
156	
157	// ParseSnapshot parses and strictly validates one snapshot document: required
158	// fields must be present and well-typed, no known field may be declared twice
159	// within the same object (even with identical values, a null first, or a
160	// spelling equivalent under Unicode case folding or JSON escaping), the
161	// format version must be supported, the embedded graph must be structurally
162	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
163	// and the content identifier must correspond exactly to the graph. A
164	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
165	// can never be trusted as a version.
166	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
167		if err := checkDuplicateFields(data); err != nil {
168			return nil, err
169		}
170		var raw rawSnapshot
171		if err := json.Unmarshal(data, &raw); err != nil {
172			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
173		}
174		if len(raw.FormatVersion) == 0 {
175			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
176		}
177		if len(raw.ContentID) == 0 {
178			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
179		}
180		if len(raw.Graph) == 0 {
181			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
182		}
183		// An explicit JSON null is present-but-untyped and must not be silently
184		// treated as a zero value (in particular, graph:null must not read as an
185		// empty graph).
186		if isJSONNull(raw.FormatVersion) {
187			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
188		}
189		if isJSONNull(raw.ContentID) {
190			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
191		}
192		if isJSONNull(raw.Graph) {
193			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
194		}
195	
196		var version int
197		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
198			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
199		}
200		if version != SnapshotFormatVersion {
201			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
202		}
203	
204		var contentID string
205		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
206			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
207		}
208		if contentID == "" {
209			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
210		}
211	
212		var gf GraphFile
213		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
214			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
215		}
216		adj, err := graphAdjacencyFromFile(gf)
217		if err != nil {
218			return nil, err
219		}
220		if err := validateAcyclic(adj); err != nil {
221			return nil, err
222		}
223	
224		canonical, err := canonicalGraph(adj)
225		if err != nil {
226			return nil, err
227		}
228		if want := computeContentID(canonical); contentID != want {
229			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
230		}
231	
232		return &SnapshotFile{
233			FormatVersion: version,
234			ContentID:     contentID,
235			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
236		}, nil
237	}
238	
239	// errAbortScan stops the duplicate-field scan when the document is too
240	// malformed to keep walking; the regular parse then reports the syntax or
241	// type error instead.
242	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
243	
244	// checkDuplicateFields rejects a snapshot in which a known field is declared
245	// more than once within the same object: formatVersion, contentId, and graph
246	// at the top level, datasets inside graph, and name and upstreams inside each
247	// dataset record. A repeated field is ambiguous — the reader would silently
248	// keep only one declaration — so the whole snapshot is refused even when the
249	// duplicates carry identical values, the first is null, or the surviving value
250	// would pass every other check.
251	//
252	// The decoder uses UseNumber so numbers are kept verbatim instead of being
253	// converted to float64: a perfectly legal JSON number outside the float64
254	// range (such as 1e400), even one buried in an ignored unknown field's value,
255	// must not make the decoder error out and abort the whole scan — otherwise an
256	// unrelated large number placed before a repeated known field would hide that
257	// duplication. Malformed number syntax still fails and is left to the regular
258	// parse to report.
259	//
260	// Field names are compared after JSON string unescaping and with the same
261	// Unicode simple case-folding the decoder applies to its case-insensitive
262	// field lookup (equivalent to strings.EqualFold), so "name", "Name", and
263	// "name" all collide, and so do spellings that only differ in a fold
264	// equivalent rune such as "formatVerſion" (long s) and "formatVersion".
265	// Unknown fields keep their ignore-everything behavior and may repeat freely.
266	// Documents that are not shaped like a snapshot at all are left to the
267	// regular parse, which reports the structural problem.
268	func checkDuplicateFields(data []byte) error {
269		dec := json.NewDecoder(bytes.NewReader(data))
270		dec.UseNumber()
271		err := checkTopLevelObject(dec)
272		if errors.Is(err, errAbortScan) {
273			return nil
274		}
275		return err
276	}
277	
278	// checkTopLevelObject scans the top-level snapshot object for repeated
279	// formatVersion/contentId/graph declarations, descending into graph values.
280	func checkTopLevelObject(dec *json.Decoder) error {
281		tok, err := scanToken(dec)
282		if err != nil {
283			return err
284		}
285		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
286			return nil // not an object: the regular parse reports the type error
287		}
288		seen := make(map[string]bool, 3)
289		for dec.More() {
290			key, err := scanKey(dec)
291			if err != nil {
292				return err
293			}
294			field, known := snapshotField(key)
295			if known {
296				if seen[field] {
297					return duplicateFieldError(field, "at the top level of the snapshot")
298				}
299				seen[field] = true
300			}
301			if field == "graph" {
302				if err := checkGraphValue(dec); err != nil {
303					return err
304				}
305			} else if err := skipValue(dec); err != nil {
306				return err
307			}
308		}
309		_, err = scanToken(dec) // closing '}'
310		return err
311	}
312	
313	// checkGraphValue scans one graph value for a repeated datasets declaration,
314	// descending into each dataset record of the datasets array.
315	func checkGraphValue(dec *json.Decoder) error {
316		tok, err := scanToken(dec)
317		if err != nil {
318			return err
319		}
320		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
321			// Not an object (null, array, scalar): consume any remainder and let
322			// the regular parse report the type problem.
323			return skipRest(dec, tok)
324		}
325		seen := false
326		for dec.More() {
327			key, err := scanKey(dec)
328			if err != nil {
329				return err
330			}
331			if strings.EqualFold(key, "datasets") {
332				if seen {
333					return duplicateFieldError("datasets", `in "graph"`)
334				}
335				seen = true
336				if err := checkDatasetsValue(dec); err != nil {
337					return err
338				}
339			} else if err := skipValue(dec); err != nil {
340				return err
341			}
342		}
343		_, err = scanToken(dec) // closing '}'
344		return err
345	}
346	
347	// checkDatasetsValue scans one datasets array, checking every record that is
348	// an object for repeated name/upstreams declarations.
349	func checkDatasetsValue(dec *json.Decoder) error {
350		tok, err := scanToken(dec)
351		if err != nil {
352			return err
353		}
354		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
355			return skipRest(dec, tok) // not an array: the regular parse reports it
356		}
357		for index := 0; dec.More(); index++ {
358			if err := checkDatasetRecord(dec, index); err != nil {
359				return err
360			}
361		}
362		_, err = scanToken(dec) // closing ']'
363		return err
364	}
365	
366	// checkDatasetRecord scans one element of the datasets array. If it is an
367	// object, name and upstreams must each be declared at most once.
368	func checkDatasetRecord(dec *json.Decoder, index int) error {
369		tok, err := scanToken(dec)
370		if err != nil {
371			return err
372		}
373		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
374			return skipRest(dec, tok) // not an object: the regular parse reports it
375		}
376		seen := make(map[string]bool, 2)
377		for dec.More() {
378			key, err := scanKey(dec)
379			if err != nil {
380				return err
381			}
382			if field, known := datasetField(key); known {
383				if seen[field] {
384					return duplicateFieldError(field, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index))
385				}
386				seen[field] = true
387			}
388			if err := skipValue(dec); err != nil {
389				return err
390			}
391		}
392		_, err = scanToken(dec) // closing '}'
393		return err
394	}
395	
396	// duplicateFieldError reports a known field declared twice, naming the field
397	// and where in the document the repetition occurred.
398	func duplicateFieldError(field, location string) error {
399		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
400	}
401	
402	// snapshotField maps a top-level key to the canonical name of the snapshot
403	// field it selects, matching the decoder's case-insensitive field lookup.
404	func snapshotField(key string) (string, bool) {
405		switch {
406		case strings.EqualFold(key, "formatVersion"):
407			return "formatVersion", true
408		case strings.EqualFold(key, "contentId"):
409			return "contentId", true
410		case strings.EqualFold(key, "graph"):
411			return "graph", true
412		}
413		return "", false
414	}
415	
416	// datasetField maps a dataset-record key to the canonical name of the record
417	// field it selects, matching the decoder's case-insensitive field lookup.
418	func datasetField(key string) (string, bool) {
419		switch {
420		case strings.EqualFold(key, "name"):
421			return "name", true
422		case strings.EqualFold(key, "upstreams"):
423			return "upstreams", true
424		}
425		return "", false
426	}
427	
428	// scanToken reads one token; any decode failure aborts the scan so the
429	// regular parse can report the malformed document.
430	func scanToken(dec *json.Decoder) (json.Token, error) {
431		tok, err := dec.Token()
432		if err != nil {
433			return nil, errAbortScan
434		}
435		return tok, nil
436	}
437	
438	// scanKey reads the next key of the object currently being walked.
439	func scanKey(dec *json.Decoder) (string, error) {
440		tok, err := scanToken(dec)
441		if err != nil {
442			return "", err
443		}
444		key, ok := tok.(string)
445		if !ok {
446			return "", errAbortScan
447		}
448		return key, nil
449	}
450	
451	// skipValue consumes one complete JSON value.
452	func skipValue(dec *json.Decoder) error {
453		tok, err := scanToken(dec)
454		if err != nil {
455			return err
456		}
457		return skipRest(dec, tok)
458	}
459	
460	// skipRest consumes the remainder of a value whose first token is tok.
461	func skipRest(dec *json.Decoder, tok json.Token) error {
462		delim, ok := tok.(json.Delim)
463		if !ok {
464			return nil // scalar, fully consumed already
465		}
466		var closer json.Delim
467		switch delim {
468		case '{':
469			closer = '}'
470			for dec.More() {
471				if _, err := scanKey(dec); err != nil {
472					return err
473				}
474				if err := skipValue(dec); err != nil {
475					return err
476				}
477			}
478		case '[':
479			closer = ']'
480			for dec.More() {
481				if err := skipValue(dec); err != nil {
482					return err
483				}
484			}
485		default:
486			return errAbortScan
487		}
488		tok, err := scanToken(dec)
489		if err != nil {
490			return err
491		}
492		if end, ok := tok.(json.Delim); !ok || end != closer {
493			return errAbortScan
494		}
495		return nil
496	}
497	
498	// CompareSnapshots returns the fixed-direction diff from old to new. Both
499	// inputs are assumed to have passed ParseSnapshot; the report is fully
500	// deterministic and identical for semantically identical comparisons.
501	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
502		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
503		newAdj := adjacencyFromValidFile(newSnap.Graph)
504	
505		added, removed := diffRelations(oldAdj, newAdj)
506	
507		var newNodes, removedNodes, changedNodes []string
508		for name := range newAdj {
509			if oldParents, ok := oldAdj[name]; !ok {
510				newNodes = append(newNodes, name)
511			} else if !stringSliceEqual(oldParents, newAdj[name]) {
512				changedNodes = append(changedNodes, name)
513			}
514		}
515		for name := range oldAdj {
516			if _, ok := newAdj[name]; !ok {
517				removedNodes = append(removedNodes, name)
518			}
519		}
520		sort.Strings(newNodes)
521		sort.Strings(removedNodes)
522		sort.Strings(changedNodes)
523	
524		common := make([]string, 0)
525		for name := range oldAdj {
526			if _, ok := newAdj[name]; ok {
527				common = append(common, name)
528			}
529		}
530		sort.Strings(common)
531	
532		rootChanges := make([]RootSourceChange, 0)
533		for _, name := range common {
534			oldRoots := rootSources(name, oldAdj)
535			newRoots := rootSources(name, newAdj)
536			if !stringSliceEqual(oldRoots, newRoots) {
537				rootChanges = append(rootChanges, RootSourceChange{
538					Dataset:  name,
539					OldRoots: oldRoots,
540					NewRoots: newRoots,
541				})
542			}
543		}
544	
545		return &CompareReport{
546			NewDatasets:       orEmptyStrings(newNodes),
547			RemovedDatasets:   orEmptyStrings(removedNodes),
548			ChangedDatasets:   orEmptyStrings(changedNodes),
549			AddedRelations:    orEmptyRelations(added),
550			RemovedRelations:  orEmptyRelations(removed),
551			RootSourceChanges: rootChanges,
552		}
553	}
554	
555	// adjacencyFromValidFile builds normalized parent adjacency from an already
556	// validated graph file.
557	func adjacencyFromValidFile(gf GraphFile) adjacency {
558		adj := make(adjacency, len(gf.Datasets))
559		for _, ds := range gf.Datasets {
560			adj[ds.Name] = uniqueSorted(ds.Upstreams)
561		}
562		return adj
563	}
564	
565	// rootSources returns the root datasets reachable from node by following
566	// direct upstream edges. A node without upstreams is itself a root and its own
567	// source, so it is included. Nodes reached by more than one path count once.
568	// The result is sorted by name and never nil.
569	func rootSources(node string, adj adjacency) []string {
570		visited := make(map[string]bool)
571		var roots []string
572		var walk func(string)
573		walk = func(current string) {
574			if visited[current] {
575				return
576			}
577			visited[current] = true
578			parents := adj[current]
579			if len(parents) == 0 {
580				roots = append(roots, current)
581				return
582			}
583			for _, parent := range parents {
584				walk(parent)
585			}
586		}
587		walk(node)
588		sort.Strings(roots)
589		return orEmptyStrings(roots)
590	}
591	
592	func orEmptyStrings(s []string) []string {
593		if s == nil {
594			return []string{}
595		}
596		return s
597	}
598	
599	func orEmptyRelations(r []Relation) []Relation {
600		if r == nil {
601			return []Relation{}
602		}
603		return r
604	}
605

