494	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
495	// The graph must be valid; an invalid graph returns an error.
496	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
497		adj, err := graphAdjacency(graph)
