505	// UnmarshalGraphFile parses the on-disk graph JSON, rebuilds the in-memory
506	// graph (parents and children), and validates it. A graph that is structurally
507	// invalid (empty names, duplicate datasets, missing upstreams, or cycles) is
508	// rejected so it cannot be used as the basis for a batch.
509	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
510		var gf GraphFile
511		if err := json.Unmarshal(data, &gf); err != nil {
512			return nil, fmt.Errorf("invalid graph JSON: %w", err)
513		}
514		graph := make(map[string]*Lineage, len(gf.Datasets))
515		for _, ds := range gf.Datasets {
516			if ds.Name == "" {
517				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
518			}
519			if _, exists := graph[ds.Name]; exists {
520				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
521			}
522			graph[ds.Name] = &Lineage{Dataset: ds.Name, Parents: uniqueSorted(ds.Upstreams)}
523		}
524		// Rebuild children from the parent edges so the in-memory graph is
525		// consistent regardless of how the file was produced.
